export function extensionLoadError(status, message) {
    const error = new Error(message);
    error.status = status;
    return error;
}
export function extensionLoadErrorStatus(error) {
    return error && typeof error === "object" && "status" in error
        ? Number(error.status)
        : undefined;
}
export function shouldRetryExtensionLoad(failureCount, error) {
    const status = extensionLoadErrorStatus(error);
    if (status === 404)
        return failureCount < 5;
    if (status === 401 || status === 403)
        return false;
    return failureCount < 1;
}
